  1	import { useEffect, useId, useRef, useState } from "react";
  2	import { AppBar, Card, ListRow, Choice, Button, AmountText, BottomSheet, formatAmount } from "../novakit";
  3	import {
  4	  FEE_PERCENT,
  5	  MAX_REMINDERS_PER_7_DAYS,
  6	  QUIET_HOURS,
  7	  formatDate,
  8	  formatTime,
  9	} from "../advance/salaryAdvance";
 10	
 11	const MISSING_MESSAGE = "To accept, tick the box to give this permission.";
 12	const TIMES = { 1: "once", 2: "twice" };
 13	
 14	/**
 15	 * S4: terms + accept.
 16	 * Everything shown comes from `terms` (getTerms). The caller only renders this
 17	 * screen when terms exist.
 18	 *
 19	 * - The cost summary is first, so it's visible without scrolling (principle 1).
 20	 * - What happens if it's late is one line, with the details in a BottomSheet.
 21	 * - The permission to collect is its own unticked checkbox. It points at the
 22	 *   repayment above instead of repeating it, and says when it ends. It starts
 23	 *   unticked every time the screen opens.
 24	 * - "Accept" stays enabled. Without the permission it shows a neutral message in the
 25	 *   action area, above the button, announced on every tap, and moves focus to the checkbox.
 26	 */
 27	export default function ReviewAccept({ Frame, terms, onAccept, onChangeAmount, onLeave }) {
 28	  const [permission, setPermission] = useState(false);
 29	  const [message, setMessage] = useState("");
 30	  const [lateOpen, setLateOpen] = useState(false);
 31	  const timer = useRef(null);
 32	  const permissionId = `${useId()}-permission`;
 33	
 34	  useEffect(() => () => clearTimeout(timer.current), []);
 35	
 36	  const due = formatDate(terms.due_date);
 37	  const time = formatTime(terms.collection.time);
 38	  const until = formatDate(terms.permission.ends_by);
 39	
 40	  function handlePermission(event) {
 41	    setPermission(event.target.checked);
 42	    clearTimeout(timer.current);
 43	    setMessage("");
 44	  }
 45	
 46	  function handleAccept() {
 47	    if (permission) {
 48	      onAccept();
 49	      return;
 50	    }
 51	    // Clear, then set again, so the status is announced on every tap, after the
 52	    // focus move has been read.
 53	    setMessage("");
 54	    document.getElementById(permissionId)?.focus();
 55	    clearTimeout(timer.current);
 56	    timer.current = setTimeout(() => setMessage(MISSING_MESSAGE), 150);
 57	  }
 58	
 59	  return (
 60	    <Frame
 61	      title="Review and accept: NovaPay"
 62	      sheet={
 63	        <BottomSheet open={lateOpen} onClose={() => setLateOpen(false)} title="What happens if it's late">
 64	          <ul className="list-disc pl-5 space-y-1 text-body text-neutral-900">
 65	            <li>Days late are counted from {due}.</li>
 66	            <li>You can pay some or all of it yourself.</li>
 67	            <li>
 68	              If your salary is delayed, tell us and we'll pause reminders. We'll still tell you before it goes into
 69	              default.
 70	            </li>
 71	            <li>
 72	              Reminders come at most {TIMES[MAX_REMINDERS_PER_7_DAYS] ?? `${MAX_REMINDERS_PER_7_DAYS} times`} a week,
 73	              never between {formatTime(QUIET_HOURS.from)} and {formatTime(QUIET_HOURS.to)}, and only to you.
 74	            </li>
 75	            <li>We won't freeze your wallet.</li>
 76	            <li>
 77	              If it's still unpaid on {until}, the advance is in default. New advances are paused and automatic
 78	              collection stops.
 79	            </li>
 80	          </ul>
 81	        </BottomSheet>
 82	      }
 83	      appBar={<AppBar title="Review and accept" onBack={onChangeAmount} backLabel="Back to amounts" />}
 84	      actions={
 85	        <>
 86	          {/* Next to the button, so it's seen where the tap happened. */}
 87	          <div>
 88	            <div role="status" className={message ? "text-body text-neutral-900 pb-3" : ""}>
 89	              {message}
 90	            </div>
 91	            <Button
 92	              size="lg"
 93	              subLabel={`Repay ${formatAmount(terms.total)} on ${due}`}
 94	              onClick={handleAccept}
 95	            >
 96	              Accept {formatAmount(terms.disbursed_amount)}
 97	            </Button>
 98	          </div>
 99	          <div className="grid grid-cols-2 gap-3">
100	            <Button variant="secondary" onClick={onChangeAmount}>
101	              Change amount
102	            </Button>
103	            <Button variant="secondary" onClick={onLeave}>
104	              Back to home
105	            </Button>
106	          </div>
107	        </>
108	      }
109	    >
110	      <Card>
111	        <h2 className="text-body font-semibold text-neutral-900">Your advance</h2>
112	        <div className="mt-1">
113	          <ListRow
114	            wrap
115	            title="You get"
116	            subtitle="Paid into your NovaPay wallet"
117	            trailing={<AmountText amount={terms.disbursed_amount} size="body" className="font-semibold" />}
118	          />
119	          <ListRow
120	            wrap
121	            title="Fee"
122	            subtitle={`${FEE_PERCENT}%, charged once`}
123	            trailing={<AmountText amount={terms.fee} size="body" className="font-semibold" />}
124	          />
125	          <ListRow
126	            wrap
127	            title={<span className="font-semibold">You repay on {due}</span>}
128	            subtitle={`At ${time} from your NovaPay wallet, once your salary arrives`}
129	            trailing={<AmountText amount={terms.total} size="body" className="font-semibold" />}
130	          />
131	        </div>
132	        <p className="text-caption text-neutral-700 mt-2">
133	          If we can only pay a lower amount, we'll show you the new terms and ask you again before paying anything.
134	        </p>
135	      </Card>
136	
137	      <Card className="space-y-2">
138	        <p className="text-body text-neutral-900">
139	          If we can't take it on {due}, we'll tell you that evening and try again when your salary next arrives.
140	        </p>
141	        <button
142	          type="button"
143	          aria-haspopup="dialog"
144	          onClick={() => setLateOpen(true)}
145	          className="rounded-sm text-body font-semibold text-brand focus:outline-none focus-visible:ring-2 focus-visible:ring-brand focus-visible:ring-offset-2"
146	        >
147	          What happens if it's late
148	        </button>
149	      </Card>
150	
151	      <Card>
152	        <Choice
153	          id={permissionId}
154	          type="checkbox"
155	          name="collection-permission"
156	          checked={permission}
157	          onChange={handlePermission}
158	          label="I allow NovaPay to take the repayment above automatically."
159	          description={`This ends automatically when it's repaid, or on ${until} at the latest.`}
160	        />
161	      </Card>
162	    </Frame>
163	  );
164	}
  1	import { useEffect, useRef, useState } from "react";
  2	import { AppBar, Card, ListRow, Button, AmountText } from "./novakit";
  3	import ChooseAmount from "./screens/ChooseAmount";
  4	import ReviewAccept from "./screens/ReviewAccept";
  5	import { PERSONAS, PROTOTYPE_TODAY, acceptTerms, getOffer, getTerms } from "./advance/salaryAdvance";
  6	
  7	/**
  8	 * NovaPay prototype in a mobile frame. Screens are built from NovaKit Lite
  9	 * (./novakit) and read every amount and date from the salary-advance module.
 10	 */
 11	
 12	// Mobile frame: a fixed 390×844 device. The AppBar and action area stay put; main scrolls.
 13	// The action area is the sticky bottom of the frame: a screen puts its main action there
 14	// so it stays visible while the content scrolls. Nothing is shown when it's empty.
 15	// `overlay` is for things that sit above the content, like a Toast. It's placed at the
 16	// bottom of the content area, just above the action area, never over the actions.
 17	// `sheet` is for a modal BottomSheet: it covers the whole frame, actions included.
 18	//
 19	// Every screen gets the same arrival: the page title becomes `title`, and after a screen
 20	// change focus moves to the screen's <h1>, so a screen reader announces where you are.
 21	// The first screen on page load keeps the browser's own focus.
 22	let hasChangedScreen = false; // set by App's navigation, never during render
 23	
 24	function PhoneFrame({ title, appBar, actions = null, overlay = null, sheet = null, children }) {
 25	  const frameRef = useRef(null);
 26	
 27	  useEffect(() => {
 28	    document.title = title;
 29	    if (hasChangedScreen) frameRef.current?.querySelector("h1")?.focus();
 30	  }, [title]);
 31	
 32	  return (
 33	    <div
 34	      ref={frameRef}
 35	      className="relative w-[390px] h-[844px] shrink-0 flex flex-col bg-neutral-50 rounded-[28px] shadow-xl overflow-hidden border border-neutral-300"
 36	    >
 37	      {appBar}
 38	
 39	      {/* The overlay sits at the bottom of the content area, so it never covers the actions. */}
 40	      <div className="relative flex-1 min-h-0 flex flex-col">
 41	        <main className="phone-scroll flex-1 min-h-0 overflow-y-auto p-4 space-y-4">{children}</main>
 42	        {overlay}
 43	      </div>
 44	
 45	      {actions ? (
 46	        <footer className="shrink-0 bg-white border-t border-neutral-200 p-4 space-y-3">{actions}</footer>
 47	      ) : null}
 48	
 49	      {sheet}
 50	    </div>
 51	  );
 52	}
 53	
 54	export default function App() {
 55	  const persona = PERSONAS.A;
 56	  const today = PROTOTYPE_TODAY;
 57	  const offer = getOffer(persona, today);
 58	
 59	  const [screen, setScreen] = useState("home");
 60	  const [amount, setAmount] = useState(null);
 61	  const [advance, setAdvance] = useState(null);
 62	  const terms = amount != null ? getTerms(persona, amount, today) : null;
 63	
 64	  // Only an eligible offer reaches the salary-advance screens. Anyone else (persona B)
 65	  // is sent to home. The terms screen needs terms; without them it goes back to the amounts.
 66	  let current = screen;
 67	  if (screen !== "home" && offer.eligibility !== "eligible") current = "home";
 68	  else if (screen === "terms" && terms == null) current = "chooseAmount";
 69	
 70	  function go(next) {
 71	    hasChangedScreen = true;
 72	    setScreen(next);
 73	  }
 74	
 75	  function leaveToHome() {
 76	    setAmount(null); // nothing is pre-selected next time
 77	    go("home");
 78	  }
 79	
 80	  function accept() {
 81	    // The permission was ticked on screen. acceptTerms is idempotent: a second tap
 82	    // returns the same advance, never a second one.
 83	    const result = acceptTerms(terms, { permission_granted: true }, today);
 84	    if (result.error) return;
 85	    setAdvance(result);
 86	    go("receipt");
 87	  }
 88	
 89	  return (
 90	    <div className="min-h-screen w-full flex justify-center items-start gap-6 py-6">
 91	      {/* Reviewer controls (src/review/) go beside the frame, never inside it. */}
 92	
 93	      {current === "home" ? (
 94	        <Home Frame={PhoneFrame} onStartAdvance={() => go("chooseAmount")} />
 95	      ) : null}
 96	
 97	      {current === "chooseAmount" ? (
 98	        <ChooseAmount
 99	          Frame={PhoneFrame}
100	          offer={offer}
101	          amount={amount}
102	          onAmountChange={setAmount}
103	          onContinue={() => go("terms")}
104	          onLeave={leaveToHome}
105	        />
106	      ) : null}
107	
108	      {current === "terms" ? (
109	        <ReviewAccept
110	          Frame={PhoneFrame}
111	          terms={terms}
112	          onAccept={accept}
113	          onChangeAmount={() => go("chooseAmount")}
114	          onLeave={leaveToHome}
115	        />
116	      ) : null}
117	
118	      {current === "receipt" ? <ReceiptPlaceholder Frame={PhoneFrame} advance={advance} onDone={leaveToHome} /> : null}
119	    </div>
120	  );
121	}
122	
123	// The starter home screen. Only the advance card's button is wired, to start the advance.
124	function Home({ Frame, onStartAdvance }) {
125	  return (
126	    <Frame title="NovaPay" appBar={<AppBar title="NovaPay" />}>
127	      <Card>
128	        <div className="text-caption text-neutral-500">Available balance</div>
129	        <div className="mt-1">
130	          <AmountText amount={4250} size="display" />
131	        </div>
132	      </Card>
133	
134	      <Card className="space-y-3">
135	        <div>
136	          <div className="text-title text-neutral-900">Need cash before payday?</div>
137	          <div className="text-body text-neutral-700 mt-1">
138	            You may qualify for a NovaPay salary advance.
139	          </div>
140	        </div>
141	        <Button size="lg" onClick={onStartAdvance}>
142	          See amounts and costs
143	        </Button>
144	      </Card>
145	
146	      <Card>
147	        <div className="text-caption text-neutral-500 mb-1">Recent activity</div>
148	        <ListRow
149	          icon="↑"
150	          title="Sent to Ahmed K."
151	          subtitle="Today, 2:14 PM"
152	          trailing={<AmountText amount={1500} size="body" />}
153	        />
154	        <ListRow
155	          icon="↓"
156	          title="Salary credited"
157	          subtitle="28 Jun"
158	          trailing={<AmountText amount={68000} size="body" />}
159	        />
160	        <ListRow
161	          icon="↑"
162	          title="Mobile top-up"
163	          subtitle="27 Jun"
164	          trailing={<AmountText amount={500} size="body" />}
165	        />
166	      </Card>
167	    </Frame>
168	  );
169	}
170	
171	// PLACEHOLDER until S5 (the receipt) is built. It exists so "Accept" leads somewhere
172	// honest. There's no back: the advance has been accepted.
173	function ReceiptPlaceholder({ Frame, advance, onDone }) {
174	  return (
175	    <Frame
176	      title="Receipt placeholder: NovaPay"
177	      appBar={<AppBar title="Salary advance" />}
178	      actions={
179	        <Button size="lg" onClick={onDone}>
180	          Done
181	        </Button>
182	      }
183	    >
184	      <Card className="space-y-1">
185	        <p className="text-body font-semibold text-neutral-900">Placeholder: receipt</p>
186	        <p className="text-body text-neutral-700">
187	          This screen isn't built yet. {advance ? "The advance was accepted." : null}
188	        </p>
189	      </Card>
190	    </Frame>
191	  );
192	}
  1	import { useEffect, useId, useRef } from "react";
  2	import Button from "./Button.jsx";
  3	
  4	/**
  5	 * BottomSheet — NovaKit Lite
  6	 * A modal sheet anchored to the bottom of its container (the phone frame).
  7	 *
  8	 * - A dialog: role="dialog", aria-modal, named by its `title`.
  9	 * - On open, focus moves to the title, so a screen reader reads where it is. Tab stays
 10	 *   inside the sheet. Escape, the Close button or a tap on the backdrop closes it, and
 11	 *   focus returns to whatever opened it.
 12	 * - Always has a visible Close button. No grab handle: swiping isn't supported.
 13	 * - Long content scrolls inside the sheet.
 14	 */
 15	export default function BottomSheet({ open, onClose, title, closeLabel = "Close", children }) {
 16	  const titleId = useId();
 17	  const sheetRef = useRef(null);
 18	  const titleRef = useRef(null);
 19	  // Held in a ref so a parent re-render doesn't re-run the open effect and move focus.
 20	  const onCloseRef = useRef(onClose);
 21	  onCloseRef.current = onClose;
 22	
 23	  useEffect(() => {
 24	    if (!open) return undefined;
 25	    const opener = document.activeElement;
 26	    titleRef.current?.focus();
 27	
 28	    function onKeyDown(event) {
 29	      if (event.key === "Escape") {
 30	        event.preventDefault();
 31	        onCloseRef.current();
 32	        return;
 33	      }
 34	      if (event.key !== "Tab") return;
 35	      // Keep Tab inside the sheet.
 36	      const focusable = [...sheetRef.current.querySelectorAll("button, a[href], input, select, textarea, summary, [tabindex]")]
 37	        .filter((el) => !el.disabled && el.tabIndex >= 0);
 38	      if (focusable.length === 0) return;
 39	      const first = focusable[0];
 40	      const last = focusable[focusable.length - 1];
 41	      if (event.shiftKey && (document.activeElement === first || document.activeElement === titleRef.current)) {
 42	        event.preventDefault();
 43	        last.focus();
 44	      } else if (!event.shiftKey && document.activeElement === last) {
 45	        event.preventDefault();
 46	        first.focus();
 47	      }
 48	    }
 49	
 50	    document.addEventListener("keydown", onKeyDown);
 51	    return () => {
 52	      document.removeEventListener("keydown", onKeyDown);
 53	      opener?.focus?.();
 54	    };
 55	  }, [open]);
 56	
 57	  if (!open) return null;
 58	  return (
 59	    <div className="absolute inset-0 z-20 flex flex-col justify-end">
 60	      <div className="absolute inset-0 bg-black/40" onClick={onClose} aria-hidden="true" />
 61	      <div
 62	        ref={sheetRef}
 63	        role="dialog"
 64	        aria-modal="true"
 65	        aria-labelledby={titleId}
 66	        className="relative max-h-full overflow-y-auto bg-white rounded-t-lg p-4 pb-6 space-y-4"
 67	      >
 68	        <h2 id={titleId} ref={titleRef} tabIndex={-1} className="text-title text-neutral-900 focus:outline-none">
 69	          {title}
 70	        </h2>
 71	        {children}
 72	        <Button variant="secondary" onClick={onClose}>
 73	          {closeLabel}
 74	        </Button>
 75	      </div>
 76	    </div>
 77	  );
 78	}

tools.description:
Open the Browser pane: pass `url` to open a browser tab at a URL (no dev server needed — use this for external sites, staging, docs, or your deployed app), OR pass `name` to start a dev server from .claude/launch.json.

Start a dev server by name from .claude/launch.json. If .claude/launch.json doesn't exist, create it first with this format:
{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "<unique-name>",
      "runtimeExecutable": "<command>",
      "runtimeArgs": ["<args>"],
      "port": <port>
    }
  ]
}
Set "runtimeExecutable" to the command (e.g. "npm"), "runtimeArgs" to the arguments (e.g. ["run", "dev"]), and "port" to the server port. An optional "url" (http/https) opens the preview there instead of http://localhost:<port>. A localhost "url" must be just the server's origin — no path or query, matching the entry's port — for example "https://localhost:8443" or "http://app.localhost:3000"; to show a specific page, navigate after the preview opens. Non-localhost URLs may carry paths and are subject to the user's permission and the organization's browsing policy. A configuration with "url" and no command attaches to an already-running server. Only include servers you actually need to preview. Reuses the server if already running. ALWAYS use this instead of Bash for running servers. If the deliverable is already published as an Artifact, update the Artifact instead of starting a server to show it.

