1	     1	/**
2	     2	 * Salary advance: the one source of truth for money and dates.
3	     3	 * Screens read from here. They never calculate money or dates themselves.
4	     4	 *
5	     5	 * Conventions
6	     6	 * - Money is whole rupees (integers).
7	     7	 * - Dates are "YYYY-MM-DD" strings and times are "HH:mm" (local time).
8	     8	 *   No Date object leaves this module.
9	     9	 * - `today` is always passed in. There is no hidden clock.
10	    10	 * - Unknown is null, never 0. An invalid request returns null, never a guess.
11	    11	 *
12	    12	 * Sources: PR = PRODUCT_REFERENCE.md, MR = docs/00-my-read.md (Assumptions and principles).
13	    13	 * "Decided" marks a call made while planning this module.
14	    14	 */
15	    15	
16	    16	// ---- Rules -----------------------------------------------------------------
17	    17	
18	    18	export const TIERS = [5000, 10000, 15000]; // PR: loan tiers
19	    19	export const FEE_PERCENT = 3; // PR: 3% of the amount paid out, charged once
20	    20	export const COLLECTION_TIME = "18:00"; // MR: payday at 6pm, once salary has landed
21	    21	export const DEFAULT_AFTER_DAYS = 30; // PR: default at 30+ days past due; day 30 counts
22	    22	export const NOT_COLLECTED_REASONS = [
23	    23	  "salary_not_arrived",
24	    24	  "salary_short",
25	    25	  "balance_dropped",
26	    26	  "salary_moved_to_bank",
27	    27	];
28	    28	
29	    29	// Reminders. MR principle 4: at most 2 a week, none between 10pm and 8am.
30	    30	export const REMINDER_TIME = "10:00";
31	    31	export const QUIET_HOURS = { from: "22:00", to: "08:00" };
32	    32	export const MAX_REMINDERS_PER_7_DAYS = 2;
33	    33	export const REMINDER_DAYS_BEFORE_DUE = 3; // 25 Jul for persona A
34	    34	export const NOTICE_DAYS_BEFORE_DEFAULT = 7; // 20 Aug for persona A
35	    35	export const LATE_REMINDER_EVERY_DAYS = 7; // PLACEHOLDER: the cadence isn't decided yet
36	    36	
37	    37	export const PROTOTYPE_TODAY = "2026-07-07"; // MR: today is 7 Jul. The year is never shown
38	    38	
39	    39	// MR: persona A is paid into NovaPay, persona B into a bank account.
40	    40	// The 4,250 balance comes from the starter home screen (decided for both).
41	    41	export const PERSONAS = {
42	    42	  A: {
43	    43	    id: "A",
44	    44	    income_source: "salaried",
45	    45	    income_verified: true,
46	    46	    salary_destination: "novapay",
47	    47	    salary_amount: 68000,
48	    48	    payday: 28,
49	    49	    limit: 10000,
50	    50	    wallet_balance: 4250,
51	    51	  },
52	    52	  B: {
53	    53	    id: "B",
54	    54	    income_source: "salaried",
55	    55	    income_verified: false,
56	    56	    salary_destination: "bank",
57	    57	    salary_amount: null,
58	    58	    payday: null,
59	    59	    limit: null,
60	    60	    wallet_balance: 4250,
61	    61	  },
62	    62	};
63	    63	
64	    64	// ---- Date helpers (private) ------------------------------------------------
65	    65	
66	    66	const DAY_MS = 24 * 60 * 60 * 1000;
67	    67	const MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
68	    68	
69	    69	const pad = (n) => String(n).padStart(2, "0");
70	    70	
71	    71	function toUtc(date) {
72	    72	  const [y, m, d] = date.split("-").map(Number);
73	    73	  return Date.UTC(y, m - 1, d);
74	    74	}
75	    75	
76	    76	function addDays(date, days) {
77	    77	  return new Date(toUtc(date) + days * DAY_MS).toISOString().slice(0, 10);
78	    78	}
79	    79	
80	    80	function daysBetween(from, to) {
81	    81	  return Math.round((toUtc(to) - toUtc(from)) / DAY_MS);
82	    82	}
83	    83	
84	    84	// The next payday strictly after today. Payday 28 exists in every month.
