296	   296	// True if adding `date` keeps every 7-day window at or under the cap.
297	   297	function fitsCap(kept, date) {
298	   298	  for (let start = addDays(date, -6); start <= date; start = addDays(start, 1)) {
299	   299	    const end = addDays(start, 6);
300	   300	    const inWindow = kept.filter((r) => r.date >= start && r.date <= end).length;
301	   301	    if (inWindow >= MAX_REMINDERS_PER_7_DAYS) return false;
302	   302	  }
303	   303	  return true;
304	   304	}
