309	   309	/**
310	   310	 * Every reminder for this advance as known today, each with a status:
311	   311	 * "sent" (on or before today), "scheduled" (later, if nothing changes) or "paused".
312	   312	 * Notices about events win over routine late reminders when the 2-a-week cap bites.
313	   313	 * Nothing is sent on or after the default date.
314	   314	 */
315	   315	export function getReminders(advance, today) {
316	   316	  const repaid_on = repaidOn(advance, today);
317	   317	  const owedOn = (date) => repaid_on == null || repaid_on >= date;
318	   318	  const due = advance.due_date;
319	   319	  const failed = failedAttemptOn(advance, due, today);
320	   320	  const lateKnown = failed != null || (today > due && owedOn(due));
321	   321	  const candidates = [];
322	   322	
323	   323	  const beforeDue = addDays(due, -REMINDER_DAYS_BEFORE_DUE);
324	   324	  if (beforeDue >= advance.accepted_on && owedOn(beforeDue)) {
325	   325	    candidates.push({ type: "before_due", date: beforeDue, time: REMINDER_TIME, priority: 1 });
326	   326	  }
327	   327	  if (failed) {
328	   328	    // Sent when the collection fails, not at 10:00: the attempt is at 6pm. Inside 8am–10pm.
329	   329	    candidates.push({ type: "not_collected", date: due, time: failed.time, priority: 0 });
330	   330	  }
331	   331	  if (lateKnown) {
332	   332	    for (let d = addDays(due, LATE_REMINDER_EVERY_DAYS); d < advance.default_date; d = addDays(d, LATE_REMINDER_EVERY_DAYS)) {
333	   333	      if (owedOn(d)) candidates.push({ type: "late", date: d, time: REMINDER_TIME, priority: 2 });
334	   334	    }
335	   335	    const beforeDefault = addDays(advance.default_date, -NOTICE_DAYS_BEFORE_DEFAULT);
336	   336	    if (owedOn(beforeDefault)) {
337	   337	      candidates.push({ type: "before_default", date: beforeDefault, time: REMINDER_TIME, priority: 0 });
338	   338	    }
339	   339	  }
340	   340	
341	   341	  const reported = advance.payroll_delay_reported_on;
342	   342	  const pausedAfter = reported != null && reported <= today ? reported : null;
343	   343	  const kept = [];
344	   344	  const out = [];
345	   345	  candidates.sort((a, b) => a.priority - b.priority || a.date.localeCompare(b.date));
346	   346	  for (const c of candidates) {
347	   347	    if (pausedAfter && c.date > pausedAfter && !NEVER_PAUSED.includes(c.type)) {
348	   348	      out.push({ ...c, status: "paused" });
349	   349	    } else if (fitsCap(kept, c.date)) {
350	   350	      kept.push(c);
351	   351	      out.push({ ...c, status: c.date <= today ? "sent" : "scheduled" });
352	   352	    }
353	   353	  }
354	   354	  return out
355	   355	    .sort((a, b) => a.date.localeCompare(b.date) || a.time.localeCompare(b.time))
356	   356	    .map(({ priority, ...reminder }) => reminder);
357	   357	}
